import {ensureJourneys,stageKey} from './journeys.js';
import {validSave} from '../shared/saves.js';
import {ensureLevels,validLevels,courseKey,migrateLevelHistory} from './levels.js';
import {validRewards} from './rewards.js';
import {collection,validateCollection} from './collection.js';
import {WORLDS} from './worlds.js';
import {builtins,validatePack,emptyRecord} from './packs.js';
import {PROFILES} from './model.js';
export const KEY='crystal-quest-arcade-v1';
export function freshData(){return {version:1,packs:Object.fromEntries(builtins().map(p=>[p.id,p])),profiles:Object.fromEntries(Object.entries(PROFILES).map(([id,p])=>[id,{activePack:id==='ari'?'earth-science':'patterns-sky',theme:p.theme,settings:{lanes:p.lanes,speed:p.speed,interval:p.interval},crystals:0,highScore:0,rewards:[],sessions:0,lastSession:null,runs:{},learning:{}}])),sound:false,narration:true,migrated:false};}
export function history(data,profile,packId){const p=data.profiles[profile];p.learning[packId]??={questions:{},concepts:{},mapping:{}};const h=p.learning[packId];h.mapping=Object.fromEntries(data.packs[packId].questions.map(q=>[q.id,q.concepts]));return h;}
export function migrate(data,storage){if(data.migrated)return;for(const [id,key,packId]of [['ari','volcano-quest-v1','earth-science'],['kal','star-quest-kal-v1','patterns-sky']]){try{const old=JSON.parse(storage.getItem(key));if(!old?.stats)continue;const h=history(data,id,packId);h.legacy={stats:old.stats,lastResult:old.lastResult||null};for(const q of data.packs[packId].questions){const r=id==='ari'?old.stats[q.id]:old.items?.[q.id]||old.stats[q.id];if(!r)continue;const rec={...emptyRecord(),presented:r.encounters||0,firstCorrect:r.firstCorrect||0,incorrect:r.incorrect||r.mistakes||0,correct:r.correct||r.firstCorrect||0,review:r.needsPractice||r.needsReview?2:0,latest:r.latest||'Imported history'};h.questions[q.id]=rec;for(const concept of q.concepts)h.concepts[concept]={...rec};}data.profiles[id].legacyAvailable=true;}catch{}}data.migrated=true;}
export function loadData(storage){let data;try{data=JSON.parse(storage.getItem(KEY));if(!validateBackup(data))throw Error();}catch{data=freshData();}migrate(data,storage);for(const p of Object.values(data.profiles)){collection(p);ensureLevels(p);migrateLevelHistory(p);ensureJourneys(p);}return data;}
export function saveData(storage,data,key=KEY){storage.setItem(key||KEY,JSON.stringify(data));}
const publicIds={ari:'emberia',kal:'luminara'};
export function exportBackup(data){const copy=structuredClone(data);const profiles={};for(const [id,world]of Object.entries(publicIds)){const p=copy.profiles[id];for(const r of new Set([...Object.values(p.runs),...Object.values(p.courses||{}),...Object.values(p.stageCourses||{}),...Object.values(p.originalCourses||{}).map(m=>m.ledger)])){r.profile=world;r.settings.name=PROFILES[id].name;}profiles[world]=p;}copy.profiles=profiles;return {format:'crystal-quest-backup-v2',data:copy};}
export function importBackup(parsed){if(parsed?.format==='crystal-quest-backup-v1'){if(!validateBackup(parsed.data))throw Error('This is not a valid Crystal Quest backup.');return parsed.data;}if(parsed?.format!=='crystal-quest-backup-v2')throw Error('This is not a valid Crystal Quest backup.');const d=structuredClone(parsed.data);if(!d?.profiles)throw Error('The backup has no profiles.');const profiles={};for(const [id,world]of Object.entries(publicIds)){const p=d.profiles[world];if(!p?.runs)throw Error('The backup is missing '+world+'.');for(const r of new Set([...Object.values(p.runs),...Object.values(p.courses||{}),...Object.values(p.stageCourses||{}),...Object.values(p.originalCourses||{}).map(m=>m.ledger)])){r.profile=id;if(r.settings)r.settings.name=PROFILES[id].name;}profiles[id]=p;}d.profiles=profiles;if(!validateBackup(d))throw Error('This is not a valid Crystal Quest backup.');return d;}
export function validateBackup(d){
 if(!d||d.version!==1||!d.packs||!d.profiles||JSON.stringify(d).length>5000000)return false;
 if(Object.entries(d.packs).some(([key,p])=>key!==p?.id||validatePack(p).length))return false;
 const settings=s=>s&&Number.isInteger(s.lanes)&&s.lanes>=3&&s.lanes<=8&&Number.isFinite(s.speed)&&s.speed>=7&&s.speed<=26&&Number.isInteger(s.interval)&&s.interval>=2&&s.interval<=20;
 for(const id of ['ari','kal']){
  const p=d.profiles[id];if(!p||!d.packs[p.activePack]||!p.learning||!p.runs||!Array.isArray(p.rewards)||![p.crystals,p.highScore,p.sessions].every(n=>Number.isFinite(n)&&n>=0)||!settings(p.settings)||!Object.hasOwn(WORLDS,p.theme)||!validateCollection(p.collection)||!validLevels(p,d.packs)||!validRewards(p))return false;
  for(const m of Object.values(p.originalCourses||{}))if(!m?.ledger||!validSave(id,m.progress))return false;for(const mode of ['runner','original'])for(const [world,j]of Object.entries(p.journeys?.[mode]||{}))if(!Object.hasOwn(WORLDS,world)||!Array.isArray(j?.completed)||j.completed.some(n=>!Number.isInteger(n)||n<0||n>2))return false;for(const h of Object.values(p.learning)){if(!h?.questions||!h.concepts)return false;for(const r of [...Object.values(h.questions),...Object.values(h.concepts)])for(const k of ['presented','firstCorrect','incorrect','laterCorrect','correct','review'])if(!Number.isFinite(r?.[k])||r[k]<0)return false;}
  for(const [key,r]of [...Object.entries(p.runs),...Object.entries(p.courses||{}),...Object.entries(p.stageCourses||{}),...Object.entries(p.originalCourses||{}).map(([k,m])=>[k,m.ledger])]){
   if(!r||(key!==r.packId&&key!==courseKey(r.packId,r.theme)&&key!==stageKey(r.packId,r.theme,r.stage))||r.profile!==id||!d.packs[r.packId]||!r.player||!settings(r.settings)||!Object.hasOwn(WORLDS,r.theme)||![r.distance,r.time,r.crystals,r.score,r.player.x,r.player.lane,r.player.y,r.player.vy,r.hearts,r.nextGroup,r.spawnIndex,r.successful,r.sinceGate,r.stageGates].every(Number.isFinite)||r.hearts<0||r.hearts>3||!Number.isInteger(r.stage)||r.stage<0||r.stage>2||!['running','question','paused','stage','victory'].includes(r.mode)||!r.stock||!['groups','gems','portals','pickups','projectiles','bursts'].every(k=>Array.isArray(r[k])&&r[k].length<1000))return false;
   if(r.pending&&(!Array.isArray(r.pending.keys)||r.pending.keys.length>5||!Number.isInteger(r.pending.index)||r.pending.index<0||r.pending.index>r.pending.keys.length||!Number.isInteger(r.pending.attempt)||r.pending.attempt<0||r.pending.packId!==r.packId))return false;
   if(['petXP','earnedXP','earnedCrystals','bankedXP','bankedCrystals'].some(k=>r[k]!==undefined&&(!Number.isSafeInteger(r[k])||r[k]<0)))return false;
   if(r.rewardEvents!==undefined&&(!Array.isArray(r.rewardEvents)||r.rewardEvents.length>5000||r.rewardEvents.some(e=>!e||typeof e.id!=='string'||e.id.length>250||!['gate','explore','stage'].includes(e.kind)||![e.crystals,e.xp,e.stage].every(Number.isSafeInteger)||e.crystals<0||e.xp<0||e.stage<0||e.stage>2)))return false;
  }
 }
 return true;
}
export function conceptMastered(pack,h,id){const linked=pack.questions.filter(q=>q.concepts.includes(id));return linked.length>0&&linked.every(q=>h.questions[q.id]?.firstCorrect>0&&!h.questions[q.id]?.review);}
export function report(pack,h){const records=pack.questions.map(q=>h.questions[q.id]).filter(Boolean),concepts=[...pack.vocabulary,...pack.facts];return {attempted:pack.questions.filter(q=>h.questions[q.id]?.presented>0).length,never:pack.questions.filter(q=>!h.questions[q.id]?.presented).length,first:records.reduce((n,r)=>n+r.firstCorrect,0),presented:records.reduce((n,r)=>n+r.presented,0),mastered:concepts.filter(c=>conceptMastered(pack,h,c.id)).length,needs:concepts.filter(c=>h.concepts[c.id]?.review>0).length,total:concepts.length};}
